from build import *

def project_scope():
 r=Report('Project Scope','DailyKhata_Project_Scope.docx','00_Project_Governance')
 r.h('Authority and purpose'); r.p('This is the replacement scope authority for DailyKhata D1 v2.0 and D2 v2.0. It consolidates the project owner instructions dated 23 September 2026 and the existing Scope Baseline v1.0. The original baseline is preserved. A recorded decision is required before a later deliverable changes a project fact, scope boundary or priority. Supervisor endorsement of these replacements has not been recorded. [G1, U1]'); r.p(DEFINITION)
 r.h('Users and operating boundary'); boundaries(r)
 r.h('Feature scope register'); scope_table(r)
 r.h('Architecture boundaries'); architecture(r)
 r.h('Feasibility and quality expectations'); r.p('The delivery unit is a four-student university FYP. A coherent capture, review, save and query workflow takes priority over optional extensions. Existing OCR and language-model components may be integrated. Model choice, hosting, database and mobile framework are implementation decisions, subject to data handling, cost and test feasibility. No production capacity, regulatory certification, perfect extraction or uptime guarantee is implied.')
 r.p('Secure user-data storage includes authenticated access, appropriate password handling, protected communication, isolation of each user\'s data, input validation and safe receipt upload handling. Assistant retrieval must respect the same user boundary. Provider credentials must be protected. These are project requirements, not a claim that security has been implemented or certified.')
 r.p('The minimum workflow must permit review of extracted values, correction of categories, saving an expense, finding it again, and editing or deleting it with consistent dependent results. Missing merchant, date or quantity data must not be silently invented. A mixed-category receipt needs a documented aggregation rule. Product matching uncertainty must remain visible enough to correct.')
 r.h('Change control'); r.p('A proposed change records the previous state, new decision, evidence or reason, affected identifiers and documents, decision authority and date. Update the Decision Log first, propagate the decision to every affected document, then repeat the consistency audit. Preserve retired identifiers as aliases or superseded records. Do not silently change Must Have into Should Have to fit a schedule.')
 r.p('Later requirements work may decompose this scope into business, functional and non-functional requirements, trace each requirement to a source and capability identifier, and define measurable acceptance criteria. It must not inherit illustrative hospital examples, concurrency values or performance targets from the D3 teaching brief as DailyKhata requirements. No Deliverable 3 is created here.')
 references(r,True); r.finish()

def standard():
 r=Report('Documentation Standard','DailyKhata_Documentation_Standard.docx','00_Project_Governance')
 r.h('Purpose and authority'); r.p('This standard governs all new DailyKhata Word documents. It replaces the working authority of Documentation Standard v1.0 while preserving that file as history. The project owner\'s instructions take precedence over older formatting. Consistent facts, traceable evidence and readable pages are required in addition to consistent typography.')
 r.h('Page and text specification')
 r.table('Mandatory Word configuration',['Element','Setting'],[('Page','A4 portrait; top and bottom 1 inch; left 1.25 inches; right 1 inch'),('Font and colour','Times New Roman; black text; restrained grey for tables or secondary elements'),('Body','12 pt; justified; 1.15 line spacing; 0 pt before and 6 pt after'),('Heading 1','16 pt bold; Word Heading 1'),('Heading 2','14 pt bold; Word Heading 2'),('Heading 3','12 pt bold; Word Heading 3'),('Heading 4','12 pt bold italic; Word Heading 4'),('Heading numbering','Automatic multilevel decimal numbering linked to Heading 1 to Heading 4; no typed heading numbers'),('Tables','10 pt or 11 pt; repeating bold header; deliberate widths; rows expand; light grey borders'),('Captions','10 pt; automatic SEQ Table or SEQ Figure field with descriptive text'),('Header and footer','9 pt or 10 pt; Times New Roman; black')],[1.4,4.62])
 r.h('Document structure'); r.p('Use a cover page, Document Control, Revision History, automatic Table of Contents, List of Figures when figures exist, List of Tables when tables exist, main content, conclusion where useful, references and appendices where applicable. Front-matter labels are unnumbered. Main headings use linked Word styles. Do not create an empty list of figures when no figures are used.')
 r.p('The cover states Beaconhouse National University, BS Computer Science, Final Year Project, DAILYKHATA, deliverable number and official title, all four team members and IDs, supervisor Nouman Ali, academic year 2026-2027 and the known submission date. A revision date is not a submission date. The canonical team is: '+ '; '.join(TEAM)+'.')
 r.p('Document Control records project, title, version, status, authors, supervisor, academic year, revision date and submission status. Revision History identifies version, date, substantive change and responsible team. Never imply supervisor approval from a filename, document status label or file timestamp.')
 r.h('Navigation captions and pagination'); r.p('Use the header DailyKhata | Final Year Project. Use the footer Beaconhouse National University | BS Computer Science and automatic Page X of Y fields. Continuous Arabic pagination counts the cover, but the cover displays no number. This convention is used across all replacement documents. Keep heading paragraphs with following content and retain widow and orphan control.')
 r.p('Create the Table of Contents from Heading 1 to Heading 3 using Word fields. Use automatic caption sequences and a generated List of Tables or List of Figures. Refresh fields and pagination in Word before final export. Do not manually type contents page numbers. Every figure needs a caption and reference in surrounding text. Major tables need a caption, readable header, consistent widths and repeating header rows when continued.')
 r.h('Language and terminology'); r.p('Use British English and en-GB proofing. Preferred forms include categorisation, digitisation, organisation, behaviour, authorised, localisation and adviser. Preserve official titles and source names where appropriate. Use DailyKhata, Chart of Accounts, AI Financial Assistant and the terms in Canonical Terminology consistently.')
 r.p('The Unicode character U+2014 is prohibited in all generated text, including metadata, headings, table cells, captions, headers, footers and diagrams. Search the full DOCX package before release and replace any occurrence with suitable punctuation. Use commas, colons, semicolons, parentheses or ordinary hyphens.')
 r.h('Evidence and requirements'); r.p('Distinguish reported evidence, attributed stakeholder statements, project-team analysis, derived requirements and proposed design decisions. Quotations must retain their source and verification status. Do not present invented interviews, participants or results as real research. Unsupported market statistics and current competitor claims must be removed or supported by traceable sources.')
 r.p('D1 establishes users, problems and scope. D2 explains elicitation and derived requirement candidates. Later D3 may formalise business, functional and non-functional requirements with validation criteria. Preserve SC and SS scope identifiers. Proposed formal identifier patterns remain BR-###, FR-[SUBSYSTEM]-### and NFR-[QUALITY]-###. Do not reuse a retired identifier for a different meaning.')
 r.p('Use Must Have, Should Have, Could Have, Future Scope and Out of Scope exactly as defined in Project Scope. A feature priority is independent of implementation status. Use shall for mandatory behaviour only within the stated priority and document stage. Record any changed fact, scope or priority in the Decision Log and propagate it consistently.')
 r.h('Quality control and release'); r.p('Check the page dimensions and margins, fonts, colours, heading styles and automatic numbering, TOC entries, page fields, headers and footers. Check table widths and continued headers, page breaks, orphan headings, blank pages, figure references and caption sequences. Review spelling flags with British English enabled, then inspect wording and canonical terminology manually.')
 r.p('Render every final page and visually inspect it for overflow, clipped text, broken tables, excessive gaps and missing glyphs. Repeat rendering after layout changes. Run a cross-document check of project definition, personas, stakeholder roles, feature priorities, evidence and exclusions. Verify source file hashes remain unchanged. Record results in the Consistency Audit, including any validation limitations.')
 r.finish()

def terminology():
 r=Report('Canonical Terminology','DailyKhata_Canonical_Terminology.docx','00_Project_Governance')
 r.h('Purpose and use'); r.p('This register fixes the language and identities shared by D1 v2.0 and D2 v2.0. A synonym can be used in an attributed quotation, but it must not silently rename a system concept. Stable scope IDs and persona IDs support later requirements traceability.')
 terms=[('DailyKhata','Personal expense management application for the approved Pakistani personal and household context.'),('Receipt digitisation','Conversion of receipt information into reviewable structured records; not a promise of perfect OCR.'),('OCR','Optical character recognition of text from a receipt image; structured extraction interprets recognised text into fields.'),('Expense transaction','A saved expense record owned by one account; distinct from a payment execution or bank transaction import.'),('Line item','An individual receipt entry with original text and available quantity and price values.'),('Automatic categorisation','System proposal of transaction and line-item expense categories, subject to confirmation or correction.'),('Expense category','Stable classification presented using a familiar label, such as Ration or Household Supplies.'),('Chart of Accounts','Internal structured accounting account register, distinct from the list of user-visible labels.'),('Accounting mapping','Link from an expense category to an internal accounting account; changing a label must not change meaning silently.'),('Item-level price history','Recorded prices over time for sufficiently identifiable products, with dates and quantity context.'),('Semantic product classification','Assignment of a canonical product type while preserving individual product, brand and original receipt text.'),('Original receipt text','Unmodified captured receipt text retained separately from corrected or inferred fields.'),('Individual product','A distinct purchasable product, including its brand and relevant pack-size or variant identity.'),('Brand','Product brand, if identifiable; not interchangeable with product type or expense category.'),('Canonical product type','Shared semantic grouping, such as Laundry Detergent, spanning distinct brands and products.'),('AI Financial Assistant','Core conversational capability grounded in authorised DailyKhata records; no payment or bank-control powers.'),('Localisation','English and Urdu adaptation, including potential right-to-left presentation and Urdu interaction; Should Have.'),('Custom category label','Renaming the user-facing label of an existing category; Should Have.'),('User-created category','Creating a new category identity and maintaining its mapping; Could Have.'),('Household expense management','One account holder records household expenses; collaboration and shared accounts are future scope.'),('Recurring-spending analysis','Assistant discussion of repeated past spending; core. Automatic recurring expense creation is future scope.'),('Unusually high spending','Data-grounded comparison or explanation by the assistant; not a committed predictive anomaly-detection service.'),('Month-to-month comparison views','Dedicated comparison presentation; Should Have. Conversational period comparisons remain Must Have.'),('Receipt image archive','Retention and retrieval of receipt images beyond processing; Should Have.'),('Design persona','A representative design profile. It is not proof that a corresponding participant fact has been independently verified.'),('Source-reported evidence','An assertion present in an original project source, preserved with its limitations.'),('Project-team analysis','Interpretation, synthesis or design reasoning; not a new observation or interview finding.')]
 r.table('Canonical concept definitions',['Preferred term','Meaning and boundary'],terms,[1.65,4.37])
 r.h('Canonical identities'); persona_section(r,False)
 r.p('Primary persona roles are P-01, P-02 and P-03. P-04 is a secondary beneficiary; P-05 is a secondary direct user. Advisers are secondary stakeholders. The development team and supervisor are internal project stakeholders. OCR, AI and hosting providers are external technical stakeholders if selected. Privacy and regulatory context is a constraint domain, not a named interviewed person or organisation. Bank and payment partners are future stakeholders only.')
 r.h('Priority and identifier rules'); r.p('SC-01 to SC-30 retain their existing meanings with clarified wording. SS-03 to SS-06 and SS-08 to SS-11 retain distinct optional capabilities. SS-01, SS-02 and SS-07 are aliases of SC-10, SC-29 and SC-28 respectively. No alias changes a priority. Consult Project Scope for the complete register.')
 r.h('Source of terminology'); r.p('Project owner scope instructions, existing governance v1.0 and original D1 and D2 provide the vocabulary. DEC-01 to DEC-20 record corrections and clarifications. New terminology requires a definition, source or design rationale and an impact check before use in later deliverables.')
 r.finish()

def decisions():
 r=Report('Decision Log','DailyKhata_Decision_Log.docx','00_Project_Governance')
 r.h('Authority and status'); r.p('All decisions below were applied on 23 September 2026 under the project owner\'s reconstruction instructions. They are documentation baseline decisions, not records of supervisor approval or newly confirmed fieldwork. Historical sources remain unchanged. D1 v2.0 and D2 v2.0 inherit these resolutions.')
 titles=['Persona age','Primary user coverage','Household persona','Shopkeeper scope','Income statement boundary','Confirmation before saving','Capture priorities','Unsupported market claims','Competitor evidence','Performance expectations','Connectivity boundary','Missing core capabilities','Assistant and future analytics','Category priorities and aliases','Document titles and format','Authority and dates','Accounting boundary','Evidence provenance','Pagination convention','Receipt and product identity']
 for idx,(ident,old,new,reason,affected) in enumerate(DECISIONS):
  r.h(ident.replace('-',' ')+' '+titles[idx])
  r.p('Previous state: '+old); r.p('Decision: '+new); r.p('Reason: '+reason); r.p('Affected documents: '+affected+'. Status: Applied to replacement baseline.')
  if ident=='DEC-15': r.p('Related source issue: the D3 brief labels its rubric as 10 marks, prints a total of 20.0, and lists component marks that sum to 20.0. Its requirements workflow is retained for compatibility; grading interpretation is left to the supervisor and does not change D1 or D2 scope.')
  if ident=='DEC-18': r.p('Related source issue: D2 describes requirement questions both as a later revisit and as following the initial interviews. Preserve the question sequence without asserting a separate visit schedule. This is reflected in reconstructed D2 under Interview technique.')
 r.h('Human confirmation register'); r.table('Facts and approvals still needing confirmation',['Item','Owner and required action','Baseline treatment'],[('Usman participant age','Project team: check the original participant record','Design persona remains 41; D2 source discrepancy is retained'),('Fieldwork provenance','Project team: provide dates, notes or recordings, consent status and participant identification basis','Original D2 is treated as reported evidence only'),('Competitor comparison','Project team: identify app versions, bank app, test dates and artefacts','Historical narrative only; no current product claims'),('Submission and endorsement','Project team and supervisor: record submission dates and review outcome','Revision dates are shown; no approval invented'),('Later validation','Project team: define device, receipt set, network and measurable targets','Quality expectations preserved without fabricated results')],[1.25,2.65,2.12])
 r.h('Future change record'); r.p('For each new decision, record an unused decision ID, date, previous state, new decision, evidence or reason, authority, affected documents and identifiers, propagation status and verification result. Confirmed corrections to source facts may replace a provisional persona resolution only through this process.')
 r.finish()

if __name__=='__main__':
 project_scope(); standard(); terminology(); decisions()
